    const tm = (dt) => dt.toLocaleTimeString('en-AU', { hour: 'numeric', minute: '2-digit' }).replace(' ', '').toLowerCase();
    const ago = (t) => { const m = Math.max(0, Math.round((Date.now() - t) / 60000)); return m < 1 ? 'just now' : m < 60 ? plural(m, 'minute') + ' ago' : plural(Math.round(m / 60), 'hour') + ' ago'; };
    const chipSt = (on) => on ? 'border:0;background:var(--primary);color:var(--primaryInk)' : 'border:1px solid var(--outline);background:var(--surface);color:var(--ink)';
    const closeMenu = (ev) => { try { ev.currentTarget.closest('details').removeAttribute('open'); } catch (x) {} };
    const D = this.data; const ME = D.me || {};
