    // ----- tabs
    const tabDefs = [['household', 'Household'], ['notify', 'Notifications'], ['layouts', 'Layouts'], ['lenders', 'Lenders'], ['brokers', 'Brokers'], ['data', 'Data and privacy']].concat(isAdmin ? [['server', 'Server']] : []);
    // a tab you cannot see (Server for non-admins, or a mistyped #name) falls back to Household
    const tab = tabDefs.some((t) => t[0] === tabWanted) ? tabWanted : 'household';
    const tabs = tabDefs.map((t) => ({ title: t[1], ['i_' + t[0]]: true, on: tab === t[0], pill: this.pill(tab === t[0]), pick: () => this.setTab(t[0]) }));
