    const roleOpts = ['Owner', 'Editor', 'Viewer'].map((v) => ({ t: v, d: descs[v], sel: !!rp && rp.baseRole === v, cls: rp && rp.baseRole === v ? 'on' : '',
      pick: async () => { if (!rp) return; this.setState({ roleFor: null }); if (rp.baseRole === v) return; if (!ownerCount(rp.id, v)) { this.flash('A household needs at least one owner'); return; } const r = await this.run('setRole', { userId: rp.id, role: v }); if (r) this.flash(r.text); } }));
